#!/usr/bin/env python3
import json,hashlib,os,sys,time,urllib.request
from pathlib import Path
from playwright.sync_api import sync_playwright
HERE=Path(__file__).parent;OUT=Path(os.environ['P10_BROWSER_OUT']);WEB=os.environ.get('P10_WEB','http://127.0.0.1:4450');API=os.environ.get('P10_API','http://127.0.0.1:4451');OUT.mkdir(parents=True,exist_ok=True);definition=json.loads((HERE/'p10-browser-v1-definition.json').read_text());cases={x['id']:{**x,'status':'not-executed','observations':[]}for x in definition['cases']};network=[]
